"use strict";

// guards: every source file opens with a purpose comment (CODEMAP section 2)

/**
 * jstack/require-purpose-header (M-1, ADR-35) — every source file opens with
 * a block comment saying what it is FOR.
 *
 * `CODEMAP.md` section 2 is generated by reading the first sentence of each
 * file's header. A file with no header appears in the map as
 * "_(no header comment)_", which is worse than useless: the map is what a
 * future agent reads instead of opening the file, so a blank row invites it
 * to guess. This rule is what makes that column trustworthy.
 *
 * It asks for a *sentence*, not a restated filename. `/** Toast. *\/` on
 * `Toast.tsx` passes the letter of the rule and fails its point, so the
 * minimum length below is a real threshold rather than a formality — a
 * useful purpose line does not fit in twenty characters.
 */
const path = require("node:path");

/** Long enough that "Toast." and "The header." cannot pass. */
const MIN_PURPOSE_CHARS = 24;

/**
 * Exempt, each for a reason.
 *
 * - generated files: their generator writes the header, and a rule that
 *   fights a generator is a rule somebody disables.
 * - `.d.ts`: type declarations carry no behaviour to explain.
 * - route files under `app/`: expo-router owns them and several are three
 *   lines re-exporting a screen. The screen has the header.
 */
function isExempt(filename) {
  const rel = path.relative(process.cwd(), filename).split(path.sep).join("/");
  return /\.generated\.tsx?$/.test(rel) || /\.d\.ts$/.test(rel) || rel.startsWith("app/");
}

module.exports = {
  meta: {
    type: "suggestion",
    docs: {
      description: "require a block comment at the top of every source file saying what it is for",
    },
    schema: [],
    messages: {
      missing: "This file has no purpose header. CODEMAP.md section 2 reads the first sentence of it; without one the map has a blank where an agent expects a description.",
      tooShort: "The purpose header is too short to say anything ({{len}} chars). Say what the file is FOR, not what it is called.",
    },
  },
  create(context) {
    const filename = context.filename ?? context.getFilename();
    if (isExempt(filename)) return {};

    return {
      Program(node) {
        // `context.sourceCode` is the modern accessor; `getSourceCode()` is
        // the one that exists everywhere this rule is invoked from,
        // including the bare `Linter.verify()` the guard test uses.
        const sourceCode = context.sourceCode ?? context.getSourceCode();
        const comments = sourceCode.getAllComments();
        const first = comments[0];
        // "at the top" means before any statement, not merely present
        const firstStatement = node.body[0];
        const isHeader =
          first != null &&
          first.type === "Block" &&
          (firstStatement == null || first.range[0] < firstStatement.range[0]);

        if (!isHeader) {
          context.report({ node, messageId: "missing" });
          return;
        }
        const text = first.value.replace(/^\*/, "").replace(/^\s*\*\s?/gm, "").replace(/\s+/g, " ").trim();
        if (text.length < MIN_PURPOSE_CHARS) {
          context.report({ node, messageId: "tooShort", data: { len: String(text.length) } });
        }
      },
    };
  },
};
